export type TokenName = (typeof TOKEN_NAMES)[number]
export type TokenMap = Partial<Record<TokenName, string>>

/** Structural variants a skin can opt into; each has a rule block in theme.css. */
export const SKIN_TRAITS = ['square-controls', 'card-sessions'] as const
export type SkinTrait = (typeof SKIN_TRAITS)[number]

export interface SkinSpec {
  key: string
  name: string
  /** Picker swatch: up to three colours. */
  colors: readonly string[]
  traits?: readonly SkinTrait[]
  /** Values for both schemes (`:root[data-skin]`). */
  tokens: TokenMap
  /** Dark-scheme overrides (`:root.dark[data-skin]`). */
  dark: TokenMap
}

