export type SkinKey = (typeof SKINS)[number]['key']
export const SKIN_KEYS = SKINS.map((s) => s.key) as [SkinKey, ...SkinKey[]]
export const skinByKey = (key: string): SkinSpec | undefined => SKINS.find((s) => s.key === key)

const block = (selector: string, tokens: TokenMap): string => {
  const entries = Object.entries(tokens)
  return entries.length ? `${selector}{${entries.map(([k, v]) => `${k}:${v}`).join(';')}}\n` : ''
}

/** The token stylesheet: base values, dark overrides, then every skin in declaration order. */
export function renderThemeCss(base: { tokens: TokenMap; dark: TokenMap } = BASE, skins: readonly SkinSpec[] = SKINS): string {
  let css = block(':root', base.tokens) + block(':root.dark', base.dark)
  for (const s of skins) {
    const sel = s.key === 'default' ? ':root:not([data-skin]),:root[data-skin="default"]' : `:root[data-skin="${s.key}"]`
    const darkSel = s.key === 'default' ? ':root.dark:not([data-skin]),:root.dark[data-skin="default"]' : `:root.dark[data-skin="${s.key}"]`
    css += block(sel, s.tokens) + block(darkSel, s.dark)
  }
  return css
}
